function routeTripMinutes(line){return Math.max(1,line.length/15*60/(1+state.upgrades.driver*.08))}
function routeCycleMinutes(line,bus){const roundTrip=routeTripMinutes(line)*2,headway=Math.max(0,Number(bus.frequencyMinutes)||0);return Math.max(roundTrip,headway)}
function processBusFares(){let totalEarned=0,runCount=0;for(const bus of state.buses){const line=getLine(bus.lineId);if(!line||!line.geometry?.length||!Number.isFinite(line.length)||line.length<=0)continue;if(!Number.isFinite(bus.startedAtGameMinute)){bus.startedAtGameMinute=state.gameMinutes;bus.tripsCompleted=0}const cycleMinutes=routeCycleMinutes(line,bus),completed=Math.floor(Math.max(0,state.gameMinutes-bus.startedAtGameMinute)/cycleMinutes),newTrips=Math.max(0,completed-(bus.tripsCompleted||0));if(!newTrips)continue;const farePerTrip=Math.max(1,Math.round(line.length*10));totalEarned+=farePerTrip*2*newTrips;runCount+=2*newTrips;bus.tripsCompleted=completed}if(!totalEarned)return;state.money+=totalEarned;state.faresEarned+=totalEarned;pendingFareToast+=totalEarned;pendingFareRuns+=runCount;$('moneyButton').textContent=money(state.money);$('balanceView').textContent=money(state.money);$('faresView').textContent=money(state.faresEarned);const now=Date.now();if(now-lastFareToast>=5000){notify(`Buses completed ${pendingFareRuns} run${pendingFareRuns===1?'':'s'} and earned ${money(pendingFareToast)}.`);pendingFareToast=0;pendingFareRuns=0;lastFareToast=now}}
