function renderStopMarkers(){stopLayer.clearLayers();if(mode!=='route')return;for(const s of areaStops()){if(state.settings.visibleStopsOnly&&!map.getBounds().contains([s.lat,s.lng]))continue;const picked=selected.includes(s.id);const kind=isStationStop(s)?'station':'';const icon=L.divIcon({className:'',html:`<span class="game-stop ${picked?'selected':''} ${kind}" style="width:${picked?18:14}px;height:${picked?18:14}px;display:block"></span>`,iconSize:[18,18],iconAnchor:[9,9]});const marker=L.marker([s.lat,s.lng],{icon,title:s.name,alt:s.name}).addTo(stopLayer);marker.bindTooltip(`${isStationStop(s)?'Interchange / Bus Station · ':''}${escapeHtml(s.name)}`,{direction:'top',offset:[0,-5]});marker.on('click',e=>{L.DomEvent.stopPropagation(e);if(mode==='route')selectStop(s)})}for(const s of state.customStops.filter(x=>shownAreaIds().includes(x.area))){if(state.settings.visibleStopsOnly&&!map.getBounds().contains([s.lat,s.lng]))continue;const icon=L.divIcon({className:'',html:`<span class="game-stop custom ${selected.includes(s.id)?'selected':''}" style="width:14px;height:14px;display:block"></span>`,iconSize:[14,14],iconAnchor:[7,7]});const marker=L.marker([s.lat,s.lng],{icon,title:s.name}).addTo(stopLayer);marker.bindTooltip(escapeHtml(s.name),{direction:'top',offset:[0,-5]});marker.on('click',()=>{if(mode==='route')selectStop(s)})}}map.on('moveend zoomend',renderStopMarkers);map.on('zoomend',updateBusPassengerVisibility);function renderMap(){routeLayer.clearLayers();depotLayer.clearLayers();busLayer.clearLayers();busMarkers.clear();for(const line of activeLines()){if(line.geometry?.length)L.polyline(line.geometry,{color:line.color||'#397b5b',weight:5,opacity:.8}).addTo(routeLayer)}renderStopMarkers();if(draftPath.length>1)L.polyline(draftPath,{color:'#d48836',weight:4,dashArray:'5 7',opacity:.9}).addTo(routeLayer);for(const depot of depotCatalog){if(!map.getBounds().contains([depot.lat,depot.lng]))continue;const owned=state.ownedDepots.includes(depot.id),icon=L.divIcon({className:'',html:`<span class="depot-map-marker ${owned?'owned':'locked'}">${owned?'D':'+'}</span>`,iconSize:[27,27],iconAnchor:[13,13]});const marker=L.marker([depot.lat,depot.lng],{icon,title:depot.name,zIndexOffset:800}).addTo(depotLayer);marker.bindTooltip(owned?`${depot.name} · ${depotBusCount(depot.id)}/15 buses`:`${depot.name} · ${depot.cost} ★ to buy`);if(!owned)marker.on('click',()=>purchaseDepot(depot.id))}for(const bus of state.buses){const line=getLine(bus.lineId);if(!line||!shownAreaIds().includes(line.area||defaultState.activeArea)||!line.geometry?.length)continue;const livery=getLivery(bus.livery),icon=L.divIcon({className:'',html:`<span class="map-bus" style="--bus-colour:${livery.color}"><span class="map-bus-passengers">${Math.floor(bus.passengers||0)}/${bus.seats}</span>${vehiclePhotoMarkup(bus,'vehicle-map-photo',livery.color)}</span>`,iconSize:[44,34],iconAnchor:[22,17]});const marker=L.marker(busPosition(bus,line),{icon,title:`${bus.name} · ${line.name}`,zIndexOffset:1200}).addTo(busLayer);marker.bindTooltip(`${escapeHtml(bus.name)} · ${escapeHtml(line.name)} · ${Math.floor(bus.passengers||0)}/${bus.seats} passengers`,{direction:'top'});marker.on('click',event=>{L.DomEvent.stopPropagation(event);toggleBusFollow(bus.id)});busMarkers.set(bus.id,marker)}updateBusPassengerVisibility();updateBusPositions()}
function selectStop(stop){const closesLoop=selected.length>=2&&stop.id===selected[0]&&isStationStop(stop)&&selected.at(-1)!==stop.id;if(closesLoop){selected.push(stop.id);updateDraft();render();notify(`${stop.name} added as the return stop.`);return}if(selected.includes(stop.id)){if(confirm(`${stop.name} is already on this line. Remove its last occurrence?`))removeStop(stop.id);return}if(!selected.length&&!isStationStop(stop)){notify('Every line must begin at an Interchange or Bus Station.');return}selected.push(stop.id);updateDraft();render()}
function removeStop(id){removeStopAt(selected.lastIndexOf(id))}
function removeStopAt(index){if(index<0||index>=selected.length)return;const stop=byId(selected[index]);selected.splice(index,1);updateDraft();render();if(stop)notify(`${stop.name} removed from this line.`)}
function busPosition(bus,line){const points=line.geometry.map(p=>L.latLng(p[0],p[1]));if(points.length<2)return points[0]||map.getCenter();const segmentLengths=[];let total=0;for(let i=1;i<points.length;i++){const d=points[i-1].distanceTo(points[i]);segmentLengths.push(d);total+=d}if(!total)return points[0];const oneWayMinutes=routeTripMinutes(line),roundTripMinutes=oneWayMinutes*2,cycleMinutes=routeCycleMinutes(line,bus),started=Number.isFinite(bus.startedAtGameMinute)?bus.startedAtGameMinute:state.gameMinutes,elapsed=Math.max(0,state.gameMinutes-started)%cycleMinutes;if(elapsed>=roundTripMinutes)return points[0];const phase=elapsed<=oneWayMinutes?elapsed/oneWayMinutes:2-elapsed/oneWayMinutes;let distance=total*phase;for(let i=0;i<segmentLengths.length;i++){const d=segmentLengths[i];if(distance<=d||i===segmentLengths.length-1){const t=d?Math.max(0,Math.min(1,distance/d)):0;return L.latLng(points[i].lat+(points[i+1].lat-points[i].lat)*t,points[i].lng+(points[i+1].lng-points[i].lng)*t)}distance-=d}return points.at(-1)}function updateBusPassengerDisplay(bus,line){const marker=busMarkers.get(bus.id);if(!marker)return;const count=Math.floor(bus.passengers||0),badge=marker.getElement()?.querySelector('.map-bus-passengers');if(badge)badge.textContent=`${count}/${bus.seats}`;marker.setTooltipContent(`${escapeHtml(bus.name)} · ${escapeHtml(line.name)} · ${count}/${bus.seats} passengers`)}
function updateBusPassengerVisibility(){if(map?.getContainer())map.getContainer().classList.toggle('bus-passenger-zoom',map.getZoom()>=17)}
function toggleBusFollow(id){if(followedBusId===id){followedBusId=null;notify('Bus follow stopped.');return}const bus=state.buses.find(item=>item.id===id),line=getLine(bus?.lineId);if(!bus||!line)return;followedBusId=id;map.setView(busPosition(bus,line),Math.max(17,map.getZoom()),{animate:true});notify(`Following ${bus.name}. Click it again to stop.`)}
function updateBusPositions(){let followedFound=false;for(const bus of state.buses){const marker=busMarkers.get(bus.id),line=getLine(bus.lineId);if(marker&&line){const position=busPosition(bus,line);marker.setLatLng(position);updateBusPassengerDisplay(bus,line);if(followedBusId===bus.id){followedFound=true;if(!map.getBounds().pad(-.25).contains(position))map.panTo(position,{animate:false})}}}if(followedBusId&&!followedFound)followedBusId=null}
function byId(id){return areaStops().find(s=>s.id===id)||state.customStops.find(s=>s.id===id)}
function updateDraft(){const stops=selected.map(byId).filter(Boolean);draftPath=[];draftDistance=0;for(let i=1;i<stops.length;i++){const leg=shortestRoadPath(stops[i-1],stops[i]);if(leg.points.length){if(draftPath.length)leg.points.shift();draftPath.push(...leg.points);draftDistance+=leg.distance}}}
function addRoadEdge(a,b){if(!roadGraph.has(a.id))roadGraph.set(a.id,[]);if(!roadGraph.has(b.id))roadGraph.set(b.id,[]);const d=map.distance([a.lat,a.lon],[b.lat,b.lon]);roadGraph.get(a.id).push({id:b.id,d});roadGraph.get(b.id).push({id:a.id,d})}
function nearestRoadNode(stop){let closest=null,best=Infinity;for(const [id,edges]of roadGraph){if(!edges.length)continue;const node=nodesById.get(id);if(!node)continue;const d=map.distance([stop.lat,stop.lng],[node.lat,node.lon]);if(d<best){best=d;closest=id}}return closest}
let nodesById=new Map();
class MinHeap{constructor(){this.a=[]}push(v){const a=this.a;a.push(v);let i=a.length-1;while(i){const p=(i-1)>>1;if(a[p].d<=v.d)break;a[i]=a[p];i=p}a[i]=v}pop(){const a=this.a;if(!a.length)return null;const top=a[0],last=a.pop();if(a.length){let i=0;while(true){let c=i*2+1;if(c>=a.length)break;if(c+1<a.length&&a[c+1].d<a[c].d)c++;if(a[c].d>=last.d)break;a[i]=a[c];i=c}a[i]=last}return top}}
function shortestRoadPath(from,to){const start=nearestRoadNode(from),end=nearestRoadNode(to);if(!start||!end)return{points:[[from.lat,from.lng],[to.lat,to.lng]],distance:map.distance([from.lat,from.lng],[to.lat,to.lng])};const heap=new MinHeap(),dist=new Map([[start,0]]),prev=new Map();heap.push({id:start,d:0});while(heap.a.length){const cur=heap.pop();if(cur.d!==dist.get(cur.id))continue;if(cur.id===end)break;for(const edge of roadGraph.get(cur.id)||[]){const nd=cur.d+edge.d;if(nd<(dist.get(edge.id)??Infinity)){dist.set(edge.id,nd);prev.set(edge.id,cur.id);heap.push({id:edge.id,d:nd})}}}if(!dist.has(end))return{points:[[from.lat,from.lng],[to.lat,to.lng]],distance:map.distance([from.lat,from.lng],[to.lat,to.lng])};const ids=[end];while(ids[0]!==start)ids.unshift(prev.get(ids[0]));const points=[[from.lat,from.lng],...ids.map(id=>{const n=nodesById.get(id);return[n.lat,n.lon]}),[to.lat,to.lng]];return{points,distance:dist.get(end)+map.distance(points[0],points[1])+map.distance(points.at(-2),points.at(-1))}}

